                    <div className='container'>
                        <div className='row'>
                            <div className='col-lg-2'>
                                <Dashboard />
                            </div>
                            <div className='col-lg-8 me-sm-auto m-0 p-0'>
                                <div className="d-flex justify-content-between">
                                    <div>
                                        <a href='/dashboard/user-list'>
                                            <p className="back-button text-dark"><FaRegArrowAltCircleLeft /> Back to User List</p>
                                        </a>
                                    </div>

                                    <div>
                                        <div className="me-3">
                                            {/* <button className="custom-nav-button-1 active" onClick={downloadInvoice}>
                                                Download PDF
                                            </button> */}
                                        </div>
                                        <button className="custom-nav-button-1 active" onClick={handleDeleteClick}>Delete <RiDeleteBin6Line /></button>
                                    </div>
                                </div>
                            </div>
                            <div className='col-lg-8 m-sm-auto m-0 p-0'>

                                <div className='liquidity-table-1 first-table-bus'>
                                    <DataTable
                                        columns={columns}
                                        data={verticalData}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>

                                <div className='liquidity-table-1 mt-5  first-second-bus'>
                                    <DataTable
                                        columns={columns1}
                                        data={verticalData1}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>

                                <div className='liquidity-table-1 mt-5'>
                                    <DataTable
                                        columns={columns2}
                                        data={verticalData2}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>

                                <div className='liquidity-table-1 mt-5'>
                                    <DataTable
                                        columns={columns3}
                                        data={verticalData3}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>

                                <div className='liquidity-table-1 mt-5 five-table-bus'>
                                    <DataTable
                                        columns={columns4}
                                        data={verticalData4}
                                        noHeader
                                        highlightOnHover
                                        dense
                                    />
                                </div>
                            </div>
                        </div>
                        <div>
                            {isVisible && (
                                <button
                                    onClick={scrollToTop}
                                    style={{
                                        position: "fixed",
                                        bottom: "70px",
                                        right: "50px",
                                        padding: "5px 16px",
                                        fontSize: "25px",
                                        backgroundColor: "var(--color-1)",
                                        color: "var(--theme-text-1)",
                                        border: "none",
                                        borderRadius: "50%",
                                        cursor: "pointer",
                                    }}
                                >
                                    ↑
                                </button>
                            )}
                        </div>
                    </div>
                </div>
                <Modal show={!!previewImage} onHide={() => setPreviewImage(null)} centered size="lg">
                    <Modal.Header className="border-0" closeButton>
                        <Modal.Title></Modal.Title>
                    </Modal.Header>
                    <Modal.Body className="text-center">
                        <img
                            src={previewImage}
                            alt="Preview"
                            style={{ maxWidth: "100%", maxHeight: "70vh" }}
                        />
                    </Modal.Body>
                    <Modal.Footer>
                        <Button variant="outline-dark" onClick={() => setPreviewImage(null)}>
                            Close
                        </Button>
                        <Button className="border-0" style={{ background: "var(--color-1)" }} onClick={handleDownload}>
                            Download
                        </Button>
                    </Modal.Footer>
                </Modal>
            </div>
        </div>
    )
}

export default Business
